package com.student.model;

/**
 * Model class representing a Student entity.
 * Demonstrates Core Java OOP concepts: Encapsulation, Constructors, and Methods.
 */
public class Student {
    private int id;
    private String name;
    private String email;
    private String course;
    private double marks;
    private String grade;

    // Constructor for creating a new student (ID generated by DB)
    public Student(String name, String email, String course, double marks) {
        this.name = name;
        this.email = email;
        this.course = course;
        setMarks(marks); // Automatically sets marks and calculates grade
    }

    // Constructor for retrieving existing student with ID
    public Student(int id, String name, String email, String course, double marks, String grade) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.course = course;
        this.marks = marks;
        this.grade = (grade != null && !grade.isEmpty()) ? grade : calculateGrade(marks);
    }

    /**
     * Calculates the letter grade based on marks obtained out of 100.
     * 
     * @param marks Marks obtained (0 to 100)
     * @return Grade letter (A+, A, B, C, D, F)
     */
    public static String calculateGrade(double marks) {
        if (marks >= 90.0) {
            return "A+";
        } else if (marks >= 80.0) {
            return "A";
        } else if (marks >= 70.0) {
            return "B";
        } else if (marks >= 60.0) {
            return "C";
        } else if (marks >= 50.0) {
            return "D";
        } else {
            return "F";
        }
    }

    // Getters and Setters (Encapsulation)
    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getCourse() {
        return course;
    }

    public void setCourse(String course) {
        this.course = course;
    }

    public double getMarks() {
        return marks;
    }

    public void setMarks(double marks) {
        this.marks = marks;
        this.grade = calculateGrade(marks);
    }

    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    @Override
    public String toString() {
        return String.format("Student[ID=%d, Name='%s', Email='%s', Course='%s', Marks=%.2f, Grade='%s']",
                id, name, email, course, marks, grade);
    }
}
